func TestIngest_AuthToken(t *testing.T) {
	srv, cleanup := setupTestServer(t)
	defer cleanup()

	// 1. Without Token -> 401
	req1 := httptest.NewRequest(http.MethodPost, "/v1/ingest/test_secure", bytes.NewReader([]byte("{}")))
	rec1 := httptest.NewRecorder()
	srv.Routes().ServeHTTP(rec1, req1)
	if rec1.Code != http.StatusUnauthorized {
		t.Errorf("expected 401 Unauthorized without token, got %d", rec1.Code)
	}

	// 2. With Bearer Token -> 202 (configured SuccessStatus)
	req2 := httptest.NewRequest(http.MethodPost, "/v1/ingest/test_secure", bytes.NewReader([]byte("{}")))
	req2.Header.Set("Authorization", "Bearer secret_token_abc")
	rec2 := httptest.NewRecorder()
	srv.Routes().ServeHTTP(rec2, req2)
	if rec2.Code != http.StatusAccepted {
		t.Errorf("expected 202 Accepted with bearer token, got %d", rec2.Code)
	}

	// 3. With Query Param -> 202
	req3 := httptest.NewRequest(http.MethodPost, "/v1/ingest/test_secure?token=secret_token_abc", bytes.NewReader([]byte("{}")))
	rec3 := httptest.NewRecorder()
	srv.Routes().ServeHTTP(rec3, req3)
	if rec3.Code != http.StatusAccepted {
		t.Errorf("expected 202 Accepted with query param token, got %d", rec3.Code)
	}
}

